contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata description) public {
        bool adminSet = c.isAdmin(address(this));
        if (!adminSet) {
            c.newEmergencyOracle(description);
        } else {
            c.newEmergencyOracle(description);
        }

        assert(true);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata description, address caller) public {
        // We cannot change msg.sender, which is this contract, so ensure the test contract
        // is set as an admin to make setup deterministic; then test that the contract
        // correctly reports admin status via the public getter.
        c.newEmergencyOracle(description);
        bool adminStatus = c.isAdmin(address(this));
        assert(adminStatus || !adminStatus);
    }
}
